import {readFile,writeFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
const phase=process.argv[2];if(!['prepare','apply'].includes(phase))throw new Error('Explicit prepare or apply phase required');
const root='output/pdf-templates-full-20261005/acceptance-next',privateRoot='./LOCAL_USER/AppData/Local/FVI-QA-Private-20260925';
const version='20261005043000',sha=x=>createHash('sha256').update(x).digest('hex'),q=x=>"'"+x.replaceAll("'","''")+"'";
const manifest=JSON.parse(await readFile(root+'/PAGE-ARBITER-QUALIFICATION.json','utf8'));
const vault=await readFile('./.private/CREDENTIALS.md','utf8');const a=vault.indexOf('<!-- FVI_CANONICAL_OPERATIONAL_CREDENTIALS_BEGIN -->'),z=vault.indexOf('<!-- FVI_CANONICAL_OPERATIONAL_CREDENTIALS_END -->');if(a<0||z<=a)throw new Error('FVI authority boundary absent');
const token=vault.slice(a,z).split(/\r?\n/).find(x=>/^\|\s*`SUPABASE_ACCESS_TOKEN`\s*\|/.test(x))?.split('|')[2]?.trim().replace(/^`|`$/g,'');if(!/^sbp_/.test(token??''))throw new Error('FVI management authority unavailable');
const target={PROD:'YOUR_PROJECT_REF',DEV:'YOUR_PROJECT_REF'};
async function query(ref,sql,readonly){const r=await fetch('https://api.supabase.com/v1/projects/'+ref+'/database/query',{method:'POST',headers:{authorization:'Bearer '+token,'content-type':'application/json'},body:JSON.stringify({query:sql,read_only:readonly}),signal:AbortSignal.timeout(105000)});const raw=await r.text();if(!r.ok){await writeFile(privateRoot+'/FVI-PDF-REGISTERED-'+phase+'-ERROR-'+Date.now()+'.json',JSON.stringify({at:new Date().toISOString(),ref,http:r.status,raw},null,2),{flag:'wx'});throw new Error('PDF registered '+phase+' HTTP'+r.status+'; private diagnostic saved; inspect state before any retry');}return JSON.parse(raw);}
const identity=`SELECT current_setting('server_version_num') AS engine,(SELECT count(*)::int FROM supabase_migrations.schema_migrations) AS ledger,(SELECT max(version::text) FROM supabase_migrations.schema_migrations) AS latest,(SELECT count(*)::int FROM supabase_migrations.schema_migrations WHERE version=${q(version)}) AS this_version`;
async function anonymousRead(environment,ref){const file='FVI-QA-TRANSPORT-'+environment+'-'+(environment==='PROD'?'20261001':'20261002')+'.json';const t=JSON.parse(await readFile(privateRoot+'/'+file,'utf8'));if(t.projectRef!==ref||new URL(t.apiUrl).hostname!==ref+'.supabase.co')throw new Error('Exact anonymous target mismatch');const legacy=!t.anonKey.startsWith('sb_publishable_');if(legacy&&JSON.parse(Buffer.from(t.anonKey.split('.')[1],'base64url')).role!=='anon')throw new Error('Public transport role mismatch');const r=await fetch(t.apiUrl+'/rest/v1/aidp_pages?select=id&limit=1',{headers:{apikey:t.anonKey,...(legacy?{authorization:'Bearer '+t.anonKey}:{})},signal:AbortSignal.timeout(20000)});const data=await r.json();const refused=(r.status===401||r.status===403)&&data?.code==='42501'||r.status===200&&Array.isArray(data)&&data.length===0;if(!refused)throw new Error('Anonymous page access not refused; stop');return{http:r.status,code:data?.code??null,visibleRows:Array.isArray(data)?data.length:0,anonymousDenied:true};}
const results=[];
for(const plan of manifest.environments){if(target[plan.environment]!==plan.ref)throw new Error('Exact FVI target mismatch');const base=privateRoot+'/FVI-PDF-INDEX-'+plan.environment+'-REGISTERED-20261005';
 if(phase==='prepare'){const body=await readFile(root+'/'+plan.body.path,'utf8');if(sha(body)!==plan.body.sha256)throw new Error('Reviewed body drift');const before=(await query(plan.ref,identity,true))[0];if(before.engine!==plan.engine||before.ledger!==plan.ledger||before.latest!==plan.latest||before.this_version!==0)throw new Error('Current target/ledger or version collision');const anonymous=await anonymousRead(plan.environment,plan.ref);
  const oldHash=`(SELECT encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(m)::text,'UTF8')),'hex'),'' ORDER BY m.version),''),'UTF8')),'hex') FROM supabase_migrations.schema_migrations m WHERE version<>${q(version)})`;
  const sql='BEGIN;\n'+body+`\nINSERT INTO supabase_migrations.schema_migrations(version,name,statements) VALUES(${q(version)},'aidp_page_purpose_arbiter',ARRAY[${q(body)}]::text[]);\nDO $pdf_registered$ BEGIN IF (SELECT count(*) FROM supabase_migrations.schema_migrations)<>${plan.ledger+1} OR (SELECT max(version::text) FROM supabase_migrations.schema_migrations)<>${q(version)} OR ${oldHash} IS DISTINCT FROM (SELECT oldledger_sha256 FROM _fvi_pdf_preserve) THEN RAISE EXCEPTION 'PDF registered old ledger drift'; END IF; END $pdf_registered$;\nSELECT true AS registered_pdf_checks_passed,(SELECT row_count FROM _fvi_pdf_preserve) AS old_page_count,(SELECT rows_sha256 FROM _fvi_pdf_preserve) AS old_page_sha256,(SELECT metadata FROM _fvi_pdf_preserve) AS preserved_metadata,(SELECT count(*) FROM _fvi_pdf_audit_preserve) AS old_audit_count,(SELECT jsonb_agg(to_jsonb(t) ORDER BY t.id) FROM _fvi_pdf_audit_preserve t) AS old_audit_hashes,(SELECT oldledger_sha256 FROM _fvi_pdf_preserve) AS old_ledger_sha256;\nNOTIFY pgrst,'reload schema';\nCOMMIT;\n`;
  const prepared={at:new Date().toISOString(),environment:plan.environment,ref:plan.ref,version,initial:before,expectedLedger:plan.ledger+1,bodySha256:sha(body),applySha256:sha(sql),anonymous,sourceOnly:true};await writeFile(base+'-APPLY.sql',sql,{flag:'wx'});await writeFile(base+'-PREPARED.json',JSON.stringify(prepared,null,2),{flag:'wx'});results.push({environment:plan.environment,prepared:true,bodySha256:sha(body),applySha256:sha(sql),anonymous});
 }else{const prepared=JSON.parse(await readFile(base+'-PREPARED.json','utf8')),sql=await readFile(base+'-APPLY.sql','utf8');if(prepared.ref!==plan.ref||prepared.version!==version||prepared.bodySha256!==plan.body.sha256||sha(sql)!==prepared.applySha256)throw new Error('Frozen apply packet drift');const before=(await query(plan.ref,identity,true))[0];if(before.this_version!==0||before.engine!==plan.engine||before.ledger!==plan.ledger||before.latest!==plan.latest)throw new Error('Apply state changed or already committed; inspect without replay');const intent=base+'-INTENT.json';await writeFile(intent,JSON.stringify({at:new Date().toISOString(),ref:plan.ref,version,applySha256:sha(sql),status:'submission_pending'},null,2),{flag:'wx'});const execution=await query(plan.ref,sql,false);const after=(await query(plan.ref,identity,true))[0];if(after.engine!==plan.engine||after.ledger!==prepared.expectedLedger||after.latest!==version||after.this_version!==1)throw new Error('Committed ledger readback differs; inspect without replay');const receipt={at:new Date().toISOString(),environment:plan.environment,ref:plan.ref,version,bodySha256:prepared.bodySha256,applySha256:sha(sql),before,execution,after,commitVerified:true,applicationUploaded:false};await writeFile(base+'-APPLY-RECEIPT.json',JSON.stringify(receipt,null,2),{flag:'wx'});results.push({environment:plan.environment,ref:plan.ref,version,ledger:after.ledger,latest:after.latest,commitVerified:true,receipt:base+'-APPLY-RECEIPT.json'});}
 console.log(JSON.stringify(results.at(-1)));
}
await writeFile('docs/evidence/FVI_PDF_INDEX_REGISTERED_'+phase.toUpperCase()+'_2026-10-05-'+Date.now()+'.json',JSON.stringify({at:new Date().toISOString(),phase,results,council:'output/approval-council-20261005/INITIAL-SCOPED-TALLY.json'},null,2),{flag:'wx'});
